import{_ as o,a as t}from"./chunks/Install45.BdJsAdnu.js";import{_ as a,o as r,c as i,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"Prerequisites","description":"","frontmatter":{},"headers":[],"relativePath":"install/prerequisites.md","filePath":"install/prerequisites.md"}'),n={name:"install/prerequisites.md"};function l(p,e,c,d,h,m){return r(),i("div",null,[...e[0]||(e[0]=[s('<p>You need an Android phone.</p><p><img src="https://www.android.com/static/images/logos/andy-peace.png" alt="https://www.android.com/static/images/logos/andy-peace.png"></p><ul><li>Minimum supported Android version is 8.0 (Android 7 support was retired in the <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12th Jul 2026</a> release).</li><li>If you will connect xDrip to a sensor, your phone must support Bluetooth Low Energy (BLE): you can use utilities <a href="https://play.google.com/store/apps/details?id=com.treeteam.blechecker" target="_blank" rel="noreferrer">like this one</a> to check.</li><li>If you want to use the embedded master - follower function of xDrip (called xDrip Sync), both phones must have <a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">Google Play Services</a> installed.</li><li>In order to use NFC scanning features for Libre 1 and 2/2+ (EU only) sensors, or to connect directly to a Libre 2/2+ (EU) sensor, your phone needs a compatible NFC reader.</li><li>If using Android 16 and above make sure you use a recent version of xDrip (at least the <a href="./download.html#latest-release">latest release</a>, we&#39;ll talk about it later: continue reading).</li></ul><h3 id="google-play-services" tabindex="-1">Google Play Services <a class="header-anchor" href="#google-play-services" aria-label="Permalink to &quot;Google Play Services&quot;">​</a></h3><p>​ <img src="http://www.gstatic.com/android/market_images/web/favicon_v3.ico" alt="http://www.gstatic.com/android/market_images/web/favicon_v3.ico"></p><p>If your phone doesn&#39;t have Google Play Services (some Huawei and Chinese phones don&#39;t), you can still use xDrip but not the xDrip Sync function that relies on them as stated above.<br> You can experience unexpected issues with alternative OS based on Android.<br> In this case make sure you <a href="./../use/sync.html#disable-sync">disable Sync functions</a>.</p><h3 id="family-link" tabindex="-1">Family Link <a class="header-anchor" href="#family-link" aria-label="Permalink to &quot;Family Link&quot;">​</a></h3><img src="https://families.google/intl/it_ALL/familylink/static/img/fl-icon.svg" style="zoom:25%;"><p>To install xDrip on a phone monitored by <a href="https://families.google.com/families" target="_blank" rel="noreferrer">Google Family Link</a> <strong>you must disable it</strong> until you&#39;ve installed the app.<br> If you want to enable it again afterwards, make sure xDrip has all rights and no time limitations.</p><h3 id="work-profile" tabindex="-1">Work profile <a class="header-anchor" href="#work-profile" aria-label="Permalink to &quot;Work profile&quot;">​</a></h3><img src="https://developer.android.com/static/images/work/cards/briefcase_600px.png" style="zoom:15%;"><p>If you use a company-controlled phone, you might not be able to install xDrip due to corporate policies.</p><p>You can try to sideload the app with <a href="./../troubleshoot/ADB.html#smartphone">Android Debug</a> using a computer after enabling developer options on your phone. Remember to delete xDrip in your work profile if necessary, as it might be installed in both environments.</p><h3 id="phone-time-accuracy" tabindex="-1">Phone time accuracy <a class="header-anchor" href="#phone-time-accuracy" aria-label="Permalink to &quot;Phone time accuracy&quot;">​</a></h3><p>Synchronize your phone clock to the network (Android Settings -&gt; <a href="https://support.google.com/android/answer/2841106" target="_blank" rel="noreferrer">Date &amp; Time</a>).<br> Make sure you are in the correct time zone and daylight settings are matching it.</p><img src="'+o+'" style="zoom:65%;"><h3 id="energy-savings" tabindex="-1">Energy savings <a class="header-anchor" href="#energy-savings" aria-label="Permalink to &quot;Energy savings&quot;">​</a></h3><p><strong><a href="./../troubleshoot/savings.html">Disable</a></strong> all phone energy savings/battery Android settings before installing xDrip.<br> You can try to restore some after verifying xDrip is working correctly; <strong>never</strong> optimize xDrip.</p><br><h3 id="play-protect" tabindex="-1">Play protect <a class="header-anchor" href="#play-protect" aria-label="Permalink to &quot;Play protect&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Note</p><p>Usually Google Play Protect doesn&#39;t stop xDrip but it might stop <a href="./../use/OOP.html">OOP</a>.</p></div><p>If xDrip stops working every night between midnight and 3am, try to disable Google Play Protect.<br> Since this is an important safety feature for your phone, be sure to avoid using it to download unknown links and games: keep your CGM phone as safe as possible if you decide to disable Play Protect.</p><p>You will find Google Play Protect in your phone Play Store app&#39;s settings.</p><img src="'+t+'" style="zoom:75%;"><br><p><a href="./download.html">Proceed to downloading xDrip</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.15" target="_blank" rel="noreferrer"><em>Last modified 18/7/2026</em></a></p>',28)])])}const f=a(n,[["render",l]]);export{y as __pageData,f as default};
